// 포스트를 태그별로 필터링하는 함수
export const filterPostsByTag = (posts, tag) => {
  if (!tag) return posts
  
  return posts.filter(post => {
    const tags = post.frontmatter.tags || []
    return tags.includes(tag)
  })
}

// 이미지 src 처리 함수 (메모이제이션을 위해 분리)
export const processImageSrc = (src) => {
  if (!src) return null
  
  let imageSrc = src.trim()
  
  // 빈 문자열이나 너무 짧은 URL 제외
  if (imageSrc.length <= 3) {
    return null
  }
  
  // data URI나 플레이스홀더 제외
  if (imageSrc.startsWith('data:') || 
      imageSrc.includes('placeholder') || 
      imageSrc.includes('loading') ||
      imageSrc.includes('blur-up') ||
      imageSrc.includes('traced')) {
    return null
  }
  
  // URL 디코딩
  try {
    imageSrc = decodeURIComponent(imageSrc)
  } catch (e) {
    // 디코딩 실패시 원본 사용
  }
  
  // 상대 경로를 절대 경로로 변환
  if (imageSrc.startsWith('./') || imageSrc.startsWith('../')) {
    imageSrc = imageSrc.replace(/^\.\.?\//, '/')
  }
  
  // Gatsby static 경로 처리
  if (!imageSrc.startsWith('http') && !imageSrc.startsWith('/') && !imageSrc.startsWith('//')) {
    imageSrc = '/' + imageSrc
  }
  
  // 프로토콜 상대 URL 처리
  if (imageSrc.startsWith('//')) {
    imageSrc = 'https:' + imageSrc
  }
  
  // 유효한 이미지 확장자인지 확인
  const imageExtensions = ['.png', '.jpg', '.jpeg', '.gif', '.webp', '.avif', '.svg']
  const hasValidExtension = imageExtensions.some(ext => 
    imageSrc.toLowerCase().includes(ext)
  )
  
  // 확장자가 없지만 Gatsby 처리된 이미지일 수 있음 (쿼리 파라미터 포함)
  const isGatsbyImage = imageSrc.includes('static/') || 
                        imageSrc.includes('images/') ||
                        imageSrc.includes('?') ||
                        imageSrc.includes('#')
  
  if (!hasValidExtension && !isGatsbyImage) {
    return null
  }
  
  return imageSrc
}

// HTML에서 이미지 URL 추출 함수 (최적화 버전)
export const extractFirstImage = (() => {
  // 정규식들을 한 번만 컴파일하여 재사용
  const gifPatterns = [
    /<img[^>]+src="([^">]*\.gif[^">]*)"[^>]*>/i,
    /<img[^>]+data-main-image[^>]+src="([^">]*\.gif[^">]*)"[^>]*>/i,
    /<picture[^>]*>[\s\S]*?<img[^>]+src="([^">]*\.gif[^">]*)"[\s\S]*?<\/picture>/i,
    /<source[^>]+srcset="([^">]*\.gif[^">]*)"[^>]*>/i,
  ]
  
  const imagePatterns = [
    // Gatsby v5 Sharp 이미지들
    /<img[^>]+data-gatsby-image-ssr[^>]+src="([^">]+)"[^>]*>/i,
    /<img[^>]+data-main-image[^>]+src="([^">]+)"[^>]*>/i,
    /<img[^>]+class="[^"]*gatsby-resp-image[^"]*"[^>]+src="([^">]+)"[^>]*>/i,
    
    // srcset에서 가장 큰 이미지 추출
    /<img[^>]+srcset="([^">]+)"[^>]*>/i,
    
    // 일반 img 태그들
    /<img[^>]+src="([^">]+\.(png|jpe?g|webp|avif|svg))"[^>]*>/i,
    /<img[^>]+src="([^">]+)"[^>]*>/i,
    
    // picture 태그 내의 source와 img
    /<picture[^>]*>[\s\S]*?<source[^>]+srcset="([^">]+)"[\s\S]*?<\/picture>/i,
    /<picture[^>]*>[\s\S]*?<img[^>]+src="([^">]+)"[\s\S]*?<\/picture>/i,
    
    // Gatsby StaticImage 컴포넌트
    /<div[^>]+class="[^"]*gatsby-image-wrapper[^"]*"[^>]*>[\s\S]*?<img[^>]+src="([^">]+)"/i,
    
    // 일반적인 이미지 패턴들
    /<figure[^>]*>[\s\S]*?<img[^>]+src="([^">]+)"[\s\S]*?<\/figure>/i,
    /<a[^>]*>[\s\S]*?<img[^>]+src="([^">]+)"[\s\S]*?<\/a>/i,
  ]

  return (html) => {
    if (!html) {
      return null
    }
    
    // 1순위: gif 파일 찾기 (애니메이션 우선)
    for (const pattern of gifPatterns) {
      const match = html.match(pattern)
      if (match && match[1]) {
        const imageSrc = processImageSrc(match[1])
        if (imageSrc) {
          return imageSrc
        }
      }
    }
    
    // 2순위: 다른 이미지 파일들
    for (let i = 0; i < imagePatterns.length; i++) {
      const pattern = imagePatterns[i]
      const match = html.match(pattern)
      
      if (match && match[1]) {
        let imageSrc = match[1]
        
        // srcset의 경우 가장 큰 이미지 선택
        if (imageSrc.includes(',')) {
          const srcsetItems = imageSrc.split(',').map(item => item.trim())
          // 가장 큰 해상도의 이미지 선택 (마지막 항목이 보통 가장 큼)
          const bestSrc = srcsetItems[srcsetItems.length - 1].split(' ')[0]
          imageSrc = bestSrc
        }
        
        const processedSrc = processImageSrc(imageSrc)
        if (processedSrc) {
          return processedSrc
        }
      }
    }
    
    return null
  }
})() 